<include file="Public:header"/><script type="text/javascript" src="{pigcms{$static_path}js/area_pca.js"></script>		<div class="mainbox">			<div id="nav" class="mainnav_title">				<ul>					<a href="{pigcms{:U('index')}" class="on">饭票充值模板列表</a>					<a href="{pigcms{:U('add')}">添加饭票充值模板</a>				</ul>			</div>			<table class="search_table" width="100%">				<tr>					<td>						<form action="{pigcms{:U('Meal_card/index')}" method="get">							<input type="hidden" name="c" value="Meal_card"/>							<input type="hidden" name="a" value="index"/>							筛选: <input type="text" name="keyword" class="input-text" placeholder="请输入模板名称" value="{pigcms{$_GET['keyword']}"/>							<font color="#000">时间筛选：</font>							<input type="text" class="input-text" name="begin_time" style="width:120px;" id="d4311"  value="{pigcms{$_GET.begin_time}" onfocus="WdatePicker({readOnly:true,dateFmt:'yyyy-MM-dd'})"/>			   							<input type="text" class="input-text" name="end_time" style="width:120px;" id="d4311" value="{pigcms{$_GET.end_time}" onfocus="WdatePicker({readOnly:true,dateFmt:'yyyy-MM-dd'})"/>							<input type="submit" style="margin-right:20px;" value="查询" class="button"/>							<notempty name="export">							<a href="javascript:void(0)" onclick="exports()" class="button" style="float:right;margin-right: 10px;">导出用户</a>							</notempty>						</form>					</td>				</tr>			</table>			<form name="myform" id="myform" action="" method="post">				<div class="table-list">					<table width="100%" cellspacing="0">						<colgroup>							<col/>							<col/>							<col/>							<col/>							<col/>							<col/>							<col/>							<col/>							<col width="180" align="center"/>						</colgroup>						<thead>							<tr>								<th><a href="{pigcms{:U('User/index',array('sort'=>'uid'))}" style="color:blue;">ID</a></th>								<th>创建日期</th>								<th>模板名称</th>								<th>商家引用总数</th>								<th>充值次数</th>								<th>充值成功次数</th>								<th>充值金额</th>								<th>模板有效期</th>								<th class="textcenter">状态</th>								<th class="textcenter">操作</th>							</tr>						</thead>						<tbody>							<if condition="is_array($list)">								<volist name="list" id="vo">									<tr>										<td>{pigcms{$vo.id}</td>										<td>{pigcms{$vo.create_time|date='Y-m-d H:i:s',###}</td>										<td><a href="{pigcms{:U('buy_list',array('id'=>$vo['id']))}">{pigcms{$vo.name}</a></td>										<td>{pigcms{$vo.merchant_str}</td>										<td>{pigcms{$vo.recharge_count}</td>										<td>{pigcms{$vo.sum_money}</td>										<if condition="$vo.effective_day gt 0">										<td>{pigcms{$vo.effective_time|date='Y-m-d H:i:s',###}</td>										<else/>										<td>永久有效</td>										</if>										<td class="textcenter"><if condition="$vo['status'] eq 1"><font color="green">正常</font><else /><font color="red">禁用</font></if></td>										<td class="textcenter">											<a href="{pigcms{:U('add',array('id'=>$vo['id']))}">												编辑											</a>											<if condition="$vo.status neq 1">											| <a href="javascript:void(0);" class="delete_row" parameter="id={pigcms{$vo.id}" url="{pigcms{:U('delete_card')}">删除</a>											</if>										</td>									</tr>								</volist>								<tr><td class="textcenter pagebar" colspan="12">{pigcms{$pagebar}</td></tr>							<else/>								<tr><td class="textcenter red" colspan="12">列表为空！</td></tr>							</if>						</tbody>					</table>				</div>			</form>		</div>		<script>		var url = "{pigcms{$config.site_url}"		var export_url = "{pigcms{:U('User/export')}"</script><script type="text/javascript" src="{pigcms{$static_public}js/export.js"> </script><include file="Public:footer"/>